def sub(path, old, new):
    s=open(path,encoding='utf-8').read()
    if old not in s:
        print('MISSING in',path,':',old[:70]); return
    open(path,'w',encoding='utf-8').write(s.replace(old,new,1))
sub('database-efficiency.md','| WAL per day | Recorded at the first rehearsal; E3 triggers if rate-limit writes are the largest share | - |','| WAL per day | Recorded at the first rehearsal and again after the limiter split (E3); the drop is reported | An unexplained doubling week on week |')
